const startMeta = $('1. Stamp Start Time & Targets').first().json;
const httpRes = $input.first()?.json || {};
const now = Date.now();
const elapsedMs = Math.max(1, now - Number(startMeta.start_time_ms || now));
const statusCode = Number(httpRes.statusCode || httpRes.error?.httpCode || httpRes.error?.statusCode || (httpRes.error ? 503 : 0));
const isHealthy = statusCode === 200;
const cutoff = now - 24 * 60 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const prior = Array.isArray(staticData.checks24h) ? staticData.checks24h : [];
prior.push({ checked_at_ms: now, status_code: statusCode, elapsed_ms: elapsedMs });
const samples = prior.filter(sample => Number(sample.checked_at_ms) >= cutoff);
staticData.checks24h = samples;
const passed = samples.filter(sample => sample.status_code === 200).length;
return [{ json: {
  check_id: startMeta.check_id, checked_url: startMeta.target_frontend_url,
  timestamp: new Date(now).toISOString(), status_code: statusCode,
  is_healthy_200: isHealthy, is_high_latency: isHealthy && elapsedMs > 1500,
  response_time_ms: elapsedMs, elapsed_time_includes_retries: true,
  sla_status: !isHealthy ? 'CRITICAL_OUTAGE' : (elapsedMs > 1500 ? 'DEGRADED_LATENCY' : 'HEALTHY_OK'),
  rolling_24h_uptime_pct: samples.length ? Number((passed / samples.length * 100).toFixed(2)) : null,
  rolling_24h_checks: samples.length, retries_configured: 3,
  error_message: httpRes.error?.message || (statusCode !== 200 ? `HTTP ${statusCode} returned` : 'None')
} }];

const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const samples = (Array.isArray(staticData.checks24h) ? staticData.checks24h : []).filter(sample => Number(sample.checked_at_ms) >= cutoff);
staticData.checks24h = samples;
const passed = samples.filter(sample => sample.status_code === 200).length;
const latencies = samples.map(sample => Number(sample.elapsed_ms)).filter(Number.isFinite).sort((a,b) => a-b);
const p95 = latencies.length ? latencies[Math.ceil(latencies.length * 0.95) - 1] : null;
const avg = latencies.length ? Math.round(latencies.reduce((sum,value) => sum + value,0) / latencies.length) : null;
return [{ json: {
  report_date: new Date().toISOString().slice(0,10),
  target_url: $env.TARGET_WEBAPP_URL || 'https://demo.realworld.io',
  total_checks_24h: samples.length, successful_checks: passed, failed_checks: samples.length - passed,
  uptime_percentage: samples.length ? `${(passed / samples.length * 100).toFixed(2)}%` : 'No data',
  avg_elapsed_ms: avg, p95_elapsed_ms: p95,
  note: samples.length ? 'Based on checks from the last 24 hours; times include retries.' : 'No checks were recorded in the last 24 hours.'
} }];

